/// Given a non-empty slice `a` of integers and a half-open subarray range `[s, e)`,
/// returns an index `min_i` in `[s, e)` such that `a[min_i]` is the minimum element
/// in that subarray. Assumes `0 <= s < e <= a.len()`.
pub fn find_min_index(a: &[i32], s: usize, e: usize) -> usize {
    // Optional sanity-check of the preconditions
    debug_assert!(s < e && e <= a.len(), "Invalid subarray range");

    let mut min_i = s;
    for i in (s + 1)..e {
        if a[i] < a[min_i] {
            min_i = i;
        }
    }
    min_i
}

